import java.util.*; public class Week05Problem04{static double rowAverage(int[]a){long sum=0;for(int v:a)sum+=v;return a.length==0?0:(double)sum/a.length;}static int classifyMatches(int[][]a,double t){int n=0;for(int[]r:a)if(rowAverage(r)>=t)n++;return n;}public static void main(String[]z){Scanner s=new Scanner(System.in);int r=s.nextInt(),c=s.nextInt();int[][]a=new int[r][c];for(int i=0;i<r;i++)for(int j=0;j<c;j++)a[i][j]=s.nextInt();double t=s.nextDouble();for(int i=0;i<r;i++)System.out.printf("Row %d average: %.2f%n",i+1,rowAverage(a[i]));System.out.println("Classified: "+classifyMatches(a,t));}}